	private String transform(String stylesheetName, String xml, String infoXml) throws Exception {
		Files.writeString(tempDir.resolve("info"), infoXml, StandardCharsets.UTF_8);
		Path xmlPath = tempDir.resolve(stylesheetName + ".xml");
		Files.writeString(xmlPath, xml, StandardCharsets.UTF_8);

		Transformer transformer = newTransformer(stylesheetName);
		StringWriter html = new StringWriter();
		transformer.transform(new StreamSource(xmlPath.toFile()), new StreamResult(html));
		return html.toString();
	}

	private static Transformer newTransformer(String stylesheetName) throws Exception {
		TransformerFactory factory = TransformerFactory.newInstance();
		Path stylesheetPath = Path.of("src/main/webapp/transformations", stylesheetName);
		StreamSource stylesheet = new StreamSource(stylesheetPath.toFile());
		stylesheet.setSystemId(stylesheetPath.toUri().toString());
		Templates templates = factory.newTemplates(stylesheet);
		return templates.newTransformer();
	}

	private static String queryResultXml() {
		StringBuilder xml = new StringBuilder();
		xml.append("<?xml version=\"1.0\"?>\n");
		xml.append("<sparql:sparql xmlns:sparql=\"http://www.w3.org/2005/sparql-results#\" ")
				.append("xmlns:workbench=\"https://rdf4j.org/schema/workbench#\">\n");
		xml.append("  <sparql:head>\n");
		xml.append("    <sparql:link href=\"info\"/>\n");
		xml.append("    <sparql:variable name=\"value\"/>\n");
		xml.append("  </sparql:head>\n");
		xml.append("  <sparql:results>\n");
		xml.append("    <sparql:result>\n");
		xml.append("      <sparql:binding name=\"value\"><sparql:literal>row</sparql:literal></sparql:binding>\n");
		xml.append("    </sparql:result>\n");
		xml.append("  </sparql:results>\n");
		xml.append("  <workbench:metadata>\n");
		xml.append("    <workbench:query-text>").append(QUERY_TEXT).append("</workbench:query-text>\n");
		xml.append("    <workbench:query-language>SPARQL</workbench:query-language>\n");
		xml.append("    <workbench:infer>false</workbench:infer>\n");
		xml.append("    <workbench:query-timeout>17</workbench:query-timeout>\n");
		xml.append("    <workbench:query-request-id>query-1</workbench:query-request-id>\n");
		xml.append("    <workbench:query-result-status>completed</workbench:query-result-status>\n");
		xml.append("    <workbench:total-result-count>42</workbench:total-result-count>\n");
		xml.append("  </workbench:metadata>\n");
		xml.append("</sparql:sparql>\n");
		return xml.toString();
	}

	private static String queryPageXml(String queryTimeout) {
		StringBuilder xml = new StringBuilder();
		xml.append("<?xml version=\"1.0\"?>\n");
		xml.append("<sparql:sparql xmlns:sparql=\"http://www.w3.org/2005/sparql-results#\">\n");
		xml.append("  <sparql:head><sparql:link href=\"info\"/></sparql:head>\n");
		xml.append("  <sparql:results><sparql:result>\n");
		appendBinding(xml, "query", QUERY_TEXT);
		appendBinding(xml, "queryLn", "SPARQL");
		if (queryTimeout != null) {
			appendBinding(xml, "query-timeout", queryTimeout);
		}
		xml.append("  </sparql:result></sparql:results>\n");
		xml.append("</sparql:sparql>\n");
		return xml.toString();
	}

	private static String informationXml() {
		StringBuilder xml = new StringBuilder();
		xml.append("<?xml version=\"1.0\"?>\n");
		xml.append("<sparql:sparql xmlns:sparql=\"http://www.w3.org/2005/sparql-results#\">\n");
		xml.append("  <sparql:head><sparql:link href=\"info\"/></sparql:head>\n");
		xml.append("  <sparql:results><sparql:result>\n");
		appendBinding(xml, "version", "information-version-sentinel");
		appendBinding(xml, "os", "information-os-sentinel");
		appendBinding(xml, "jvm", "information-jvm-sentinel");
		appendBinding(xml, "user", "information-user-sentinel");
		appendBinding(xml, "memory-used", "information-used-memory-sentinel");
		appendBinding(xml, "maximum-memory", "information-maximum-memory-sentinel");
		xml.append("  </sparql:result></sparql:results>\n");
		xml.append("</sparql:sparql>\n");
		return xml.toString();
	}

