	private static void appendBinding(StringBuilder xml, String name, String value) {
		xml.append("      <sparql:binding name=\"")
				.append(name)
				.append("\"><sparql:literal>")
				.append(value)
				.append("</sparql:literal></sparql:binding>\n");
	}

